  1	import { router, useFocusEffect, useLocalSearchParams } from 'expo-router';
  2	import { StatusBar } from 'expo-status-bar';
  3	import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
  4	import {
  5	  AppState,
  6	  BackHandler,
  7	  ScrollView,
  8	  StyleSheet,
  9	  View,
 10	  type LayoutChangeEvent,
 11	  type NativeScrollEvent,
 12	  type NativeSyntheticEvent,
 13	} from 'react-native';
 14	import Animated, { useReducedMotion } from 'react-native-reanimated';
 15	import { useSafeAreaInsets } from 'react-native-safe-area-context';
 16	
 17	import { CARD_BACKGROUNDS } from '@/components/today/backgrounds';
 18	import { CapsuleVault, type JustSealed } from '@/components/today/capsule-vault';
 19	import { CardOverlay, OVERLAY_MS, type CardRect } from '@/components/today/card-overlay';
 20	import { DreamFlow, DreamTabs, type DreamTab } from '@/components/today/dream-flow';
 21	import { FutureCard } from '@/components/today/future-card';
 22	import { animate, TOAST } from '@/components/today/motion';
 23	import { QuoteCard } from '@/components/today/quote-card';
 24	import { ShareFlow } from '@/components/today/share-flow';
 25	import { StreakBar } from '@/components/today/streak-bar';
 26	import { openTab, TAB_BAR_HEIGHT, TabBar, type Tab } from '@/components/today/tab-bar';
 27	import { TalkCard } from '@/components/today/talk-card';
 28	import { WriteCard } from '@/components/today/write-card';
 29	import { BrandFonts } from '@/constants/theme';
 30	import { useDreams } from '@/hooks/use-dreams';
 31	import { usePaywall } from '@/hooks/use-paywall';
 32	import { loadCapsules, sealCapsule } from '@/lib/capsules';
 33	import { isVoiceAgentAvailable } from '@/lib/deepgram/native-audio';
 34	import { loadProfileName } from '@/lib/profile';
 35	import { weekDays } from '@/utils/entries';
 36	import { currentStreak } from '@/utils/garden';
 37	import {
 38	  activeCard,
 39	  formatClock,
 40	  LOCK_OPTIONS,
 41	  longDate,
 42	  quoteOfDay,
 43	  shortDate,
 44	  todayGreeting,
 45	  unlockDate,
 46	  type DreamSource,
 47	  type Fragment,
 48	} from '@/utils/today';
 49	
 50	const CARD_COUNT = 4;
 51	const GAP = 10;
 52	/** Space above the first card, and below the last. */
 53	const EDGE = 6;
 54	/** Space between the cards and the sides of the screen, so they read as cards. */
 55	const SIDE = 12;
 56	/** Just the top of the next card peeks out under the one in view. */
 57	const PEEK = 40;
 58	/** Cards never get shorter than this, even on very small phones. */
 59	const MIN_CARD = 520;
 60	const TOAST_MS = 2200;
 61	
 62	/** What an opened card shows. */
 63	type OverlayContent =
 64	  | { kind: 'dream'; source: DreamSource; text?: string; fragments?: Fragment[] }
 65	  | { kind: 'share' }
 66	  | { kind: 'vault'; justSealed: JustSealed | null };
 67	
 68	type Overlay = OverlayContent & { card: number; rect: CardRect; pill: string; open: boolean };
 69	
 70	/**
 71	 * Home ("/home"), from the Afterdream Today design: a vertical feed of four full-height
 72	 * cards (yap or write, talk, today's quote, a note to future you) that snap into place,
 73	 * above a black tab bar. A dream, the quote or the time capsule opens its card into
 74	 * a full screen.
 75	 */
 76	export default function HomeScreen() {
 77	  const insets = useSafeAreaInsets();
 78	  const reduceMotion = useReducedMotion();
 79	
 80	  // Read once: the name doesn't change while the screen is up.
 81	  const [name] = useState(loadProfileName);
 82	  // "Now" moves on whenever Home comes back into view or the app is reopened, so a new
 83	  // day brings a new quote even if the app was left open overnight.
 84	  const [now, setNow] = useState(() => new Date());
 85	  const refreshNow = useCallback(() => setNow(new Date()), []);
 86	  useFocusEffect(refreshNow);
 87	  useEffect(() => {
 88	    const sub = AppState.addEventListener('change', (state) => {
 89	      if (state === 'active') refreshNow();
 90	    });
 91	    return () => sub.remove();
 92	  }, [refreshNow]);
 93	  const quote = useMemo(() => quoteOfDay(now), [now]);
 94	  // Told dreams, for the streak and this week's days (reloads whenever Home comes back into view).
 95	  const { dreams } = useDreams();
 96	  // Yapping and time capsules are paid: the guard nudges near the end of the trial, stops after it.
 97	  const { guard, reminder } = usePaywall();
 98	  const streak = useMemo(() => currentStreak(dreams, now), [dreams, now]);
 99	  const week = useMemo(() => weekDays(dreams, now), [dreams, now]);
100	
101	  const [screen, setScreen] = useState({ width: 0, height: 0 });
102	  // The feed's height before any keyboard shrank it, so cards keep their size while typing.
103	  const [areaHeight, setAreaHeight] = useState(0);
104	  const [active, setActive] = useState(0);
105	  const [writing, setWriting] = useState(false);
106	  const [saved, setSaved] = useState(false);
107	  const [capsules, setCapsules] = useState(loadCapsules);
108	  const [overlay, setOverlay] = useState<Overlay | null>(null);
109	  // The dream reading's tabs, shown in the top bar once the reading is ready.
110	  const [dreamTab, setDreamTab] = useState<DreamTab>('analysis');
111	  const [dreamReady, setDreamReady] = useState(false);
112	  const [toast, setToast] = useState<{ id: number; text: string } | null>(null);
113	  const toastTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
114	  const cards = useRef<(View | null)[]>([]);
115	  const feed = useRef<ScrollView>(null);
116	  // Patterns' "Had another dream?" lands here asking to yap or type straight away.
117	  const { start } = useLocalSearchParams<{ start?: string }>();
118	  const startWith = start === 'yap' || start === 'type' ? start : undefined;
119	
120	  const cardHeight = Math.max(MIN_CARD, areaHeight - PEEK);
121	  const interval = cardHeight + GAP;
122	  const contentHeight = EDGE * 2 + CARD_COUNT * cardHeight + (CARD_COUNT - 1) * GAP;
123	  const maxScroll = Math.max(0, contentHeight - areaHeight);
124	  // The last card can't scroll all the way up, so it snaps to the end instead.
125	  const snaps = Array.from({ length: CARD_COUNT }, (_, i) => Math.min(i * interval, maxScroll));
126	  const tabBarBottom = Math.max(insets.bottom, 8);
127	  const displayName = name ?? 'you';
128	
129	  function onFeedLayout(event: LayoutChangeEvent) {
130	    const { height } = event.nativeEvent.layout;
131	    setAreaHeight((current) => (writing ? current : height));
132	  }
133	
134	  function onScroll(event: NativeSyntheticEvent<NativeScrollEvent>) {
135	    const next = activeCard(event.nativeEvent.contentOffset.y, interval, CARD_COUNT);
136	    if (next !== active) setActive(next);
137	  }
138	
139	  function showToast(text: string) {
140	    if (toastTimer.current) clearTimeout(toastTimer.current);
141	    setToast((current) => ({ id: (current?.id ?? 0) + 1, text }));
142	    toastTimer.current = setTimeout(() => setToast(null), TOAST_MS);
143	  }
144	
145	  /** Grows the card at `index` into a full screen showing `content`. */
146	  function openCard(index: number, pill: string, content: OverlayContent) {
147	    const card = cards.current[index];
148	    if (!card) return;
149	    card.measureInWindow((x, y, width, height) => {
150	      setOverlay({ ...content, card: index, pill, rect: { x, y, width, height }, open: true });
151	    });
152	  }
153	
154	  const closeCard = useCallback(() => {
155	    setOverlay((current) => (current ? { ...current, open: false } : current));
156	    setTimeout(() => setOverlay((current) => (current && !current.open ? null : current)), OVERLAY_MS + 20);
157	  }, []);
158	
159	  // Android's back button closes an opened card instead of leaving the app.
160	  useFocusEffect(
161	    useCallback(() => {
162	      if (!overlay) return;
163	      const sub = BackHandler.addEventListener('hardwareBackPress', () => {
164	        closeCard();
165	        return true;
166	      });
167	      return () => sub.remove();
168	    }, [overlay, closeCard])
169	  );
170	
171	  function interpret(card: number, pill: string, dream: { source: DreamSource; text?: string; fragments?: Fragment[] }) {
172	    setDreamTab('analysis');
173	    setDreamReady(false);
174	    openCard(card, pill, { kind: 'dream', ...dream });
175	  }
176	
177	  function seal(recording: { uri: string; seconds: number }, lock: number) {
178	    const option = LOCK_OPTIONS[lock];
179	    const opens = unlockDate(new Date(), option.months);
180	    try {
181	      setCapsules(sealCapsule(recording.uri, recording.seconds, opens));
182	    } catch (error) {
183	      console.warn('Could not keep the capsule recording', error);
184	      showToast('couldn’t keep that note — try again');
185	      return;
186	    }
187	    openCard(3, '⧗ time capsule', { kind: 'vault', justSealed: { lockLabel: option.label, unlockDate: longDate(opens) } });
188	  }
189	
190	  function toggleSave() {
191	    setSaved(!saved);
192	    if (!saved) showToast('saved to your thoughts');
193	  }
194	
195	  function pickTab(tab: Tab) {
196	    if (!openTab(tab, 'today')) showToast(`${tab} is coming soon ✦`);
197	  }
198	
199	  function renderOverlay(current: Overlay) {
200	    switch (current.kind) {
201	      case 'dream':
202	        return (
203	          <DreamFlow
204	            source={current.source}
205	            text={current.text}
206	            fragments={current.fragments}
207	            tab={dreamTab}
208	            onReady={() => setDreamReady(true)}
209	            onToast={showToast}
210	            reduceMotion={reduceMotion}
211	            bottomInset={insets.bottom}
212	            onVisualize={(id) =>
213	              guard('visualize', () => {
214	                router.push({ pathname: '/visualize', params: { id } });
215	                closeCard();
216	              })
217	            }
218	            onDone={(wasSaved) => {
219	              closeCard();
220	              if (wasSaved) showToast('saved to entries ✦');
221	            }}
222	          />
223	        );
224	      case 'share':
225	        return (
226	          <ShareFlow
227	            quote={quote}
228	            date={shortDate(now)}
229	            photo={CARD_BACKGROUNDS[2]}
230	            reduceMotion={reduceMotion}
231	            bottomInset={insets.bottom}
232	            onToast={showToast}
233	          />
234	        );
235	      case 'vault':
236	        return (
237	          <CapsuleVault
238	            capsules={capsules}
239	            justSealed={current.justSealed}
240	            name={displayName}
241	            reduceMotion={reduceMotion}
242	            bottomInset={insets.bottom}
243	            onToast={showToast}
244	            onClose={closeCard}
245	          />
246	        );
247	    }
248	  }
249	
250	  return (
251	    <View style={styles.screen} onLayout={(e) => setScreen({ width: e.nativeEvent.layout.width, height: e.nativeEvent.layout.height })}>
252	      <StatusBar style="light" />
253	      <View style={{ marginTop: insets.top }}>
254	        <StreakBar streak={streak} week={week} />
255	      </View>
256	      <View style={styles.area} onLayout={onFeedLayout}>
257	        {areaHeight > 0 && (
258	          <ScrollView
259	            ref={feed}
260	            style={StyleSheet.absoluteFill}
261	            contentContainerStyle={styles.feed}
262	            showsVerticalScrollIndicator={false}
263	            snapToOffsets={snaps}
264	            decelerationRate="fast"
265	            scrollEnabled={!writing}
266	            keyboardShouldPersistTaps="handled"
267	            scrollEventThrottle={32}
268	            onScroll={onScroll}>
269	            <View ref={(view) => void (cards.current[0] = view)} collapsable={false}>
270	              <WriteCard
271	                height={cardHeight}
272	                active={active === 0}
273	                reduceMotion={reduceMotion}
274	                greeting={todayGreeting(name, now.getHours())}
275	                onWritingChange={setWriting}
276	                onSubmit={(text) => interpret(0, '✎ from your words', { source: 'write', text })}
277	                onRecorded={(text, seconds) => interpret(0, `◉ ${formatClock(Math.max(1, seconds))} recorded`, { source: 'yap', text })}
278	                // Yap opens the companion already talking, so there is nothing to tap twice.
279	                onSpeak={() =>
280	                  isVoiceAgentAvailable()
281	                    ? guard('voice', () => router.push({ pathname: '/voice', params: { autostart: '1' } }))
282	                    : showToast('yapping needs the full app build ✦')
283	                }
284	                start={startWith}
285	                onStarted={() => {
286	                  feed.current?.scrollTo({ y: 0, animated: true });
287	                  router.setParams({ start: undefined });
288	                }}
289	              />
290	            </View>
291	            <View ref={(view) => void (cards.current[1] = view)} collapsable={false}>
292	              <TalkCard
293	                height={cardHeight}
294	                active={active === 1}
295	                reduceMotion={reduceMotion}
296	                onWritingChange={setWriting}
297	                onSubmit={(fragments) => interpret(1, `✦ ${fragments.length} fragment${fragments.length > 1 ? 's' : ''}`, { source: 'talk', fragments })}
298	                onTalkOutLoud={
299	                  isVoiceAgentAvailable()
300	                    ? () => guard('voice', () => router.push({ pathname: '/voice', params: { autostart: '1' } }))
301	                    : null
302	                }
303	              />
304	            </View>
305	            <View ref={(view) => void (cards.current[2] = view)} collapsable={false}>
306	              <QuoteCard
307	                height={cardHeight}
308	                active={active === 2}
309	                reduceMotion={reduceMotion}
310	                quote={quote}
311	                date={shortDate(now)}
312	                saved={saved}
313	                onShare={() => openCard(2, 'share today’s thought', { kind: 'share' })}
314	                onToggleSave={toggleSave}
315	              />
316	            </View>
317	            <View ref={(view) => void (cards.current[3] = view)} collapsable={false}>
318	              <FutureCard
319	                height={cardHeight}
320	                active={active === 3}
321	                reduceMotion={reduceMotion}
322	                name={displayName}
323	                capsuleCount={capsules.length}
324	                onSeal={(recording, lock) => guard('capsules', () => seal(recording, lock))}
325	                onOpenCapsule={() => guard('capsules', () => openCard(3, '⧗ time capsule', { kind: 'vault', justSealed: null }))}
326	              />
327	            </View>
328	          </ScrollView>
329	        )}
330	      </View>
331	
332	      <TabBar current="today" bottomInset={tabBarBottom} onPick={pickTab} />
333	
334	      {/* The end-of-trial nudge for yapping and time capsules; the tab bar carries its own. */}
335	      {reminder}
336	
337	      {overlay && screen.width > 0 && (
338	        <CardOverlay
339	          from={overlay.rect}
340	          screen={screen}
341	          open={overlay.open}
342	          reduceMotion={reduceMotion}
343	          // The dream reading is plain dark, so the words stand out; the others keep their card's photo.
344	          photo={overlay.kind === 'dream' ? undefined : CARD_BACKGROUNDS[overlay.card]}
345	          pill={overlay.pill}
346	          headerRight={overlay.kind === 'dream' && dreamReady ? <DreamTabs tab={dreamTab} onChange={setDreamTab} /> : undefined}
347	          topInset={insets.top}
348	          onClose={closeCard}>
349	          {renderOverlay(overlay)}
350	        </CardOverlay>
351	      )}
352	
353	      {toast && (
354	        <View pointerEvents="none" style={[styles.toastRow, { bottom: TAB_BAR_HEIGHT + tabBarBottom + 20 }]}>
355	          <Animated.Text
356	            key={toast.id}
357	            accessibilityLiveRegion="polite"
358	            style={[styles.toast, animate(reduceMotion, { animationName: TOAST, animationDuration: TOAST_MS, animationTimingFunction: 'ease' })]}>
359	            {toast.text}
360	          </Animated.Text>
361	        </View>
362	      )}
363	    </View>
364	  );
365	}
366	
367	const styles = StyleSheet.create({
368	  screen: {
369	    flex: 1,
370	    backgroundColor: '#000',
371	  },
372	  area: {
373	    flex: 1,
374	  },
375	  feed: {
376	    paddingTop: EDGE,
377	    paddingBottom: EDGE,
378	    paddingHorizontal: SIDE,
379	    gap: GAP,
380	  },
381	  toastRow: {
382	    position: 'absolute',
383	    left: 0,
384	    right: 0,
385	    zIndex: 6,
386	    alignItems: 'center',
387	  },
388	  toast: {
389	    overflow: 'hidden',
390	    paddingVertical: 12,
391	    paddingHorizontal: 18,
392	    borderRadius: 22,
393	    backgroundColor: '#fff',
394	    fontFamily: BrandFonts.medium,
395	    fontSize: 14,
396	    lineHeight: 17,
397	    color: '#111',
398	  },
399	});

