     1	import { Image } from 'expo-image';
     2	import type { ComponentProps, ReactNode, Ref } from 'react';
     3	import { StyleSheet, Text, View, type ColorValue } from 'react-native';
     4	import Animated from 'react-native-reanimated';
     5	
     6	import { BrandFonts } from '@/constants/theme';
     7	
     8	import { DRIFT, DRIFT_BACK, EASE_OUT, loop, ZOOM } from './motion';
     9	
    10	/** Soft blob of light drifting behind a card's text. Positions are in the design's points. */
    11	export type Glow = {
    12	  left: number;
    13	  top: number;
    14	  width: number;
    15	  height: number;
    16	  color: string;
    17	  opacity: number;
    18	  rotate?: string;
    19	  drift: 'out' | 'back';
    20	  duration: number;
    21	};
    22	
    23	type TodayCardProps = {
    24	  height: number;
    25	  active: boolean;
    26	  reduceMotion: boolean;
    27	  /** Layered radial gradients (CSS syntax), shown while the picture loads or if it can't. */
    28	  gradient: string;
    29	  base: ColorValue;
    30	  /** Bundled background picture (`require(...)`), from CARD_BACKGROUNDS. */
    31	  photo: number;
    32	  glow: Glow;
    33	  label: string;
    34	  children: ReactNode;
    35	  ref?: Ref<View>;
    36	};
    37	
    38	/**
    39	 * One full-height card on the Today feed: a slowly zooming northern-lights picture over a gradient,
    40	 * a drifting glow, and whatever the card holds. The card in view is full size; the others
    41	 * shrink a little and dim.
    42	 */
    43	export function TodayCard({ height, active, reduceMotion, gradient, base, photo, glow, label, children, ref }: TodayCardProps) {
    44	  return (
    45	    <Animated.View
    46	      ref={ref}
    47	      accessibilityLabel={label}
    48	      style={[
    49	        styles.card,
    50	        { height, backgroundColor: base, experimental_backgroundImage: gradient },
    51	        { opacity: active ? 1 : 0.6, transform: [{ scale: active ? 1 : 0.94 }] },
    52	        !reduceMotion && { transitionProperty: ['opacity', 'transform'], transitionDuration: 500, transitionTimingFunction: EASE_OUT },
    53	      ]}>
    54	      <Animated.View style={[styles.photo, loop(reduceMotion, ZOOM, 24000)]}>
    55	        <Image source={photo} style={StyleSheet.absoluteFill} contentFit="cover" transition={300} />
    56	      </Animated.View>
    57	      <View style={styles.shade} />
    58	      <Animated.View
    59	        pointerEvents="none"
    60	        style={[
    61	          styles.glow,
    62	          {
    63	            left: glow.left,
    64	            top: glow.top,
    65	            width: glow.width,
    66	            height: glow.height,
    67	            opacity: glow.opacity,
    68	            experimental_backgroundImage: `radial-gradient(${glow.color} 0%, transparent 70%)`,
    69	          },
    70	          glow.rotate ? { transform: [{ rotate: glow.rotate }] } : null,
    71	          loop(reduceMotion, glow.drift === 'out' ? DRIFT : DRIFT_BACK, glow.duration),
    72	        ]}
    73	      />
    74	      {children}
    75	    </Animated.View>
    76	  );
    77	}
    78	
    79	type CardHeadingProps = {
    80	  /** Where the heading starts, as a share of the card's height. */
    81	  top: number;
    82	  eyebrow: string;
    83	  title: string;
    84	  style?: ComponentProps<typeof Animated.View>['style'];
    85	  titleStyle?: ComponentProps<typeof Text>['style'];
    86	};
    87	
    88	/** The small line and big question in the middle of a card, centred. */
    89	export function CardHeading({ top, eyebrow, title, style, titleStyle }: CardHeadingProps) {
    90	  return (
    91	    <Animated.View style={[styles.heading, { top: `${top * 100}%` }, style]}>
    92	      <Text style={styles.eyebrow}>{eyebrow}</Text>
    93	      <Text style={[styles.title, titleStyle]} accessibilityRole="header">
    94	        {title}
    95	      </Text>
    96	    </Animated.View>
    97	  );
    98	}
    99	
   100	/** Shared frosted-glass look for buttons and bubbles on a card. */
   101	export const glass = (alpha: number) => ({ backgroundColor: `rgba(255, 255, 255, ${alpha})` });
   102	
   103	const styles = StyleSheet.create({
