  1	import { useEffect, useRef, useState, type ReactNode } from 'react';
  2	import { Keyboard, Pressable, StyleSheet, Text, TextInput, View } from 'react-native';
  3	import Animated from 'react-native-reanimated';
  4	import Svg, { Path, Rect } from 'react-native-svg';
  5	
  6	import { BrandColors, BrandFonts } from '@/constants/theme';
  7	import { useDreamRecorder } from '@/hooks/use-dream-recorder';
  8	import { useKeyboardOverlap } from '@/hooks/use-keyboard-overlap';
  9	import { formatClock, wordCount, writeHint } from '@/utils/today';
 10	
 11	import { ease, EASE_OUT, PULSE, rise } from './motion';
 12	import { CARD_BACKGROUNDS } from './backgrounds';
 13	import { CardHeading, TodayCard } from './today-card';
 14	
 15	/** Box and heading positions from the design (a 610 pt card). */
 16	const BOX_CLOSED = 124;
 17	const BOX_OPEN = 290;
 18	const TITLE_OPEN_TOP = 96;
 19	/** Room the heading needs above the open box: its top, the two lines, and a gap. */
 20	const HEADING_ROOM = 215;
 21	const OPEN_PLACEHOLDER = 'start anywhere — a place, a face, a feeling…';
 22	
 23	/** The big yap button in the middle, and the small type / speak buttons either side. */
 24	const YAP_SIZE = 72;
 25	const SMALL_SIZE = 48;
 26	const COLUMN_GAP = 12;
 27	/** Room the heading takes (greeting plus two lines of title), to centre it in the card. */
 28	const HEADING_HEIGHT = 110;
 29	const RED = '#e05a5a';
 30	const START_DELAY_MS = 350;
 31	
 32	type WriteCardProps = {
 33	  height: number;
 34	  active: boolean;
 35	  reduceMotion: boolean;
 36	  greeting: string;
 37	  /** While typing, the feed stops scrolling so the card stays put above the keyboard. */
 38	  onWritingChange: (writing: boolean) => void;
 39	  /** Called with the written dream. */
 40	  onSubmit: (text: string) => void;
 41	  /** Called with a plain recording (once it has been turned into text) and how long it ran. */
 42	  onRecorded: (text: string, seconds: number) => void;
 43	  /** Opens the live voice companion, which starts talking on its own. */
 44	  onSpeak: () => void;
 45	  /** Starts yapping or typing as soon as the card shows (from Patterns' "Had another dream?"). */
 46	  start?: 'yap' | 'type';
 47	  /** Called once `start` has been acted on, so it only happens once. */
 48	  onStarted?: () => void;
 49	};
 50	
 51	/**
 52	 * Card 1: "what did you dream about last night?", centred, with three buttons along the
 53	 * bottom: record (left, the microphone: just say the dream into the phone, stopping sends
 54	 * it to be interpreted), yap (the big one in the middle: opens the voice companion, which
 55	 * starts the conversation on its own) and type (opens a writing space, where ↑ sends it).
 56	 */
 57	export function WriteCard({ height, active, reduceMotion, greeting, onWritingChange, onSubmit, onRecorded, onSpeak, start, onStarted }: WriteCardProps) {
 58	  const card = useRef<View>(null);
 59	  const [draft, setDraft] = useState('');
 60	  const [writing, setWriting] = useState(false);
 61	  // How far the keyboard reaches up into the card, so the box can sit just above it.
 62	  const keyboardOverlap = useKeyboardOverlap(card);
 63	
 64	  // How long the last recording ran, read when it stops (the recorder resets after).
 65	  const spoken = useRef(0);
 66	  const voice = useDreamRecorder((text) => onRecorded(text, spoken.current));
 67	  const recording = voice.phase === 'recording';
 68	  const busy = voice.phase === 'transcribing';
 69	
 70	  const hasDraft = wordCount(draft) > 0;
 71	  const open = writing || hasDraft;
 72	  const boxBottom = Math.max(22, keyboardOverlap + 12);
 73	  const boxHeight = Math.max(BOX_CLOSED, Math.min(BOX_OPEN, height - boxBottom - HEADING_ROOM));
 74	  const titleTop = open ? TITLE_OPEN_TOP : Math.round((height - HEADING_HEIGHT) / 2);
 75	
 76	  function startWriting() {
 77	    setWriting(true);
 78	    onWritingChange(true);
 79	  }
 80	
 81	  useEffect(() => {
 82	    if (!start) return;
 83	    // Waits for the screen to finish sliding in before opening the keyboard or the mic.
 84	    const timer = setTimeout(() => {
 85	      if (start === 'type') startWriting();
 86	      else onSpeak();
 87	      onStarted?.();
 88	    }, START_DELAY_MS);
 89	    return () => clearTimeout(timer);
 90	    // Only a new request should trigger this, not the handlers changing identity.
 91	    // eslint-disable-next-line react-hooks/exhaustive-deps
 92	  }, [start]);
 93	
 94	  function stopWriting() {
 95	    onWritingChange(false);
 96	    // Nothing written: go back to the mic.
 97	    if (!hasDraft) setWriting(false);
 98	  }
 99	
100	  function submit() {
101	    if (!hasDraft) return;
102	    const text = draft.trim();
103	    Keyboard.dismiss();
104	    setDraft('');
105	    setWriting(false);
106	    onSubmit(text);
107	  }
108	
109	  function stopRecording() {
110	    spoken.current = voice.durationMillis / 1000;
111	    voice.stopAndTranscribe();
112	  }
113	
114	  function recordLabel() {
115	    if (recording) return formatClock(voice.durationMillis / 1000);
116	    if (busy) return '…';
117	    return 'record';
118	  }
119	
120	  // The recorder is a small button until it is running, when it takes the big one's size.
121	  const recordSize = recording || busy ? YAP_SIZE : SMALL_SIZE;
122	
123	  return (
124	    <TodayCard
125	      ref={card}
126	      height={height}
127	      active={active}
128	      reduceMotion={reduceMotion}
129	      label="tell your dream"
130	      base="#060a16"
131	      gradient="radial-gradient(80% 35% at 50% 25%, #16543f, transparent 70%)"
132	      photo={CARD_BACKGROUNDS[0]}
133	      glow={{ left: 160, top: 330, width: 260, height: 260, color: '#46ffb4', opacity: 0.12, drift: 'out', duration: 14000 }}>
134	      {/* Tapping the card around the box puts the keyboard away. */}
135	      <Pressable style={StyleSheet.absoluteFill} onPress={Keyboard.dismiss} accessible={false} />
136	      <CardHeading
137	        top={0}
138	        eyebrow={greeting}
139	        title="what did you dream about last night?"
140	        titleStyle={styles.title}
141	        style={[{ top: titleTop }, !reduceMotion && { transitionProperty: 'top', transitionDuration: 500, transitionTimingFunction: EASE_OUT }]}
142	      />
143	
144	      {open ? (
145	        <Animated.View style={[styles.box, { bottom: boxBottom, height: boxHeight }, rise(reduceMotion, 0, 400)]}>
146	          <View style={styles.field}>
147	            <TextInput
148	              value={draft}
149	              onChangeText={setDraft}
150	              onFocus={() => onWritingChange(true)}
151	              onBlur={stopWriting}
152	              autoFocus
153	              multiline
154	              style={styles.input}
155	              placeholder={OPEN_PLACEHOLDER}
156	              placeholderTextColor="rgba(255, 255, 255, 0.7)"
157	              selectionColor={BrandColors.lime}
158	              cursorColor={BrandColors.lime}
159	              textAlignVertical="top"
160	              accessibilityLabel="Write your dream"
161	              accessibilityHint="Then press interpret"
162	            />
163	          </View>
164	          <View style={styles.footer}>
165	            <Text style={styles.hint}>{writeHint(draft, true)}</Text>
166	            <Pressable
167	              accessibilityRole="button"
168	              accessibilityLabel="Interpret"
169	              accessibilityState={{ disabled: !hasDraft }}
170	              disabled={!hasDraft}
171	              onPress={submit}
172	              hitSlop={6}>
173	              <Animated.View
174	                style={[
175	                  styles.send,
176	                  { backgroundColor: hasDraft ? BrandColors.lime : 'rgba(255, 255, 255, 0.25)', transform: [{ scale: hasDraft ? 1 : 0.9 }] },
177	                  !reduceMotion && { transitionProperty: ['backgroundColor', 'transform'], transitionDuration: 300 },
178	                ]}>
179	                <Text style={[styles.sendGlyph, { color: hasDraft ? '#111' : 'rgba(255, 255, 255, 0.7)' }]}>↑</Text>
180	              </Animated.View>
181	            </Pressable>
182	          </View>
183	        </Animated.View>
184	      ) : (
185	        <Animated.View style={[styles.controls, rise(reduceMotion, 0, 400)]}>
186	          {/* Left: just record the dream. No conversation, no connection — the phone listens. */}
187	          <View style={styles.column}>
188	            <View style={styles.slot}>
189	              {recording && !reduceMotion && (
190	                <Animated.View
191	                  style={[
192	                    styles.ring,
193	                    { animationName: PULSE, animationDuration: 1600, animationTimingFunction: 'ease-out', animationIterationCount: 'infinite' },
194	                  ]}
195	                />
196	              )}
197	              <Pressable
198	                accessibilityRole="button"
199	                accessibilityLabel={recording ? 'Stop recording' : 'Record your dream'}
200	                accessibilityState={{ busy }}
201	                disabled={busy}
202	                onPress={recording ? stopRecording : voice.start}
203	                hitSlop={8}
204	                style={({ pressed }) => pressed && styles.pressed}>
205	                <Animated.View
206	                  style={[
207	                    styles.round,
208	                    {
209	                      width: recordSize,
210	                      height: recordSize,
211	                      borderRadius: recordSize / 2,
212	                      backgroundColor: recording ? '#fff' : 'rgba(255, 255, 255, 0.2)',
213	                    },
214	                    ease(reduceMotion, ['backgroundColor', 'width', 'height', 'borderRadius']),
215	                  ]}>
216	                  {recording ? <View style={styles.stop} /> : <MicIcon dim={busy} />}
217	                </Animated.View>
218	              </Pressable>
219	            </View>
220	            <Text style={styles.label} accessibilityLiveRegion="polite">
221	              {recordLabel()}
222	            </Text>
223	          </View>
224	
225	          {/* Middle: yap — the companion picks up and starts asking straight away. */}
226	          <BigButton
227	            label="yap"
228	            hidden={recording || busy}
229	            onPress={onSpeak}
230	            reduceMotion={reduceMotion}
231	            accessibilityLabel="Yap: talk your dream through with your companion"
232	          />
233	
234	          <SideButton label="type" hidden={recording || busy} onPress={startWriting} reduceMotion={reduceMotion} accessibilityLabel="Type your dream">
235	            <PenIcon />
236	          </SideButton>
237	        </Animated.View>
238	      )}
239	    </TodayCard>
240	  );
241	}
