 1	import { useEffect, useState, type RefObject } from 'react';
 2	import { Keyboard, Platform, type View } from 'react-native';
 3	
 4	/**
 5	 * How far the on-screen keyboard reaches up into `view` (0 when hidden or clear of it),
 6	 * so something at the bottom of the view can sit just above the keyboard.
 7	 */
 8	export function useKeyboardOverlap(view: RefObject<View | null>) {
 9	  const [overlap, setOverlap] = useState(0);
10	
11	  useEffect(() => {
12	    const showEvent = Platform.OS === 'ios' ? 'keyboardWillShow' : 'keyboardDidShow';
13	    const hideEvent = Platform.OS === 'ios' ? 'keyboardWillHide' : 'keyboardDidHide';
14	    const show = Keyboard.addListener(showEvent, (event) => {
15	      view.current?.measureInWindow((_x, y, _width, height) => setOverlap(Math.max(0, y + height - event.endCoordinates.screenY)));
16	    });
17	    const hide = Keyboard.addListener(hideEvent, () => setOverlap(0));
18	    return () => {
19	      show.remove();
20	      hide.remove();
21	    };
22	  }, [view]);
23	
24	  return overlap;
25	}

