1	import { useEffect, useRef, useState, type ReactNode } from 'react';
2	import { Keyboard, Pressable, StyleSheet, Text, TextInput, View } from 'react-native';
3	import Animated from 'react-native-reanimated';
4	import Svg, { Path, Rect } from 'react-native-svg';
5	
6	import { BrandColors, BrandFonts } from '@/constants/theme';
7	import { useDreamRecorder } from '@/hooks/use-dream-recorder';
8	import { useKeyboardOverlap } from '@/hooks/use-keyboard-overlap';
9	import { formatClock, wordCount, writeHint } from '@/utils/today';
10	
11	import { ease, EASE_OUT, PULSE, rise } from './motion';
12	import { CARD_BACKGROUNDS } from './backgrounds';
13	import { CardHeading, TodayCard } from './today-card';
14	
15	/** Box and heading positions from the design (a 610 pt card). */
16	const BOX_CLOSED = 124;
17	const BOX_OPEN = 290;
18	const TITLE_OPEN_TOP = 96;
19	/** Room the heading needs above the open box: its top, the two lines, and a gap. */
20	const HEADING_ROOM = 215;
21	const OPEN_PLACEHOLDER = 'start anywhere — a place, a face, a feeling…';
22	
23	/** The big yap button in the middle, and the small type / speak buttons either side. */
24	const YAP_SIZE = 72;
25	const SMALL_SIZE = 48;
26	const COLUMN_GAP = 12;
27	/** Room the heading takes (greeting plus two lines of title), to centre it in the card. */
28	const HEADING_HEIGHT = 110;
29	const RED = '#e05a5a';
30	const START_DELAY_MS = 350;
31	
32	type WriteCardProps = {
33	  /** Height of the card's content, between the two insets. */
34	  height: number;
35	  /** Space kept clear at the top of the page, and at the bottom for the tab bar. */
36	  insetTop: number;
37	  insetBottom: number;
38	  active: boolean;
39	  reduceMotion: boolean;
40	  greeting: string;
41	  /** While typing, the feed stops scrolling so the card stays put above the keyboard. */
42	  onWritingChange: (writing: boolean) => void;
43	  /** Called with the written dream. */
44	  onSubmit: (text: string) => void;
45	  /** Called with a plain recording (once it has been turned into text) and how long it ran. */
46	  onRecorded: (text: string, seconds: number) => void;
47	  /** Opens the live voice companion, which starts talking on its own. */
48	  onSpeak: () => void;
49	  /** Starts yapping or typing as soon as the card shows (from Patterns' "Had another dream?"). */
50	  start?: 'yap' | 'type';
51	  /** Called once `start` has been acted on, so it only happens once. */
52	  onStarted?: () => void;
53	};
54	
55	/**
56	 * Card 1: "what did you dream about last night?", centred, with three buttons along the
57	 * bottom: record (left, the microphone: just say the dream into the phone, stopping sends
58	 * it to be interpreted), yap (the big one in the middle: opens the voice companion, which
59	 * starts the conversation on its own) and type (opens a writing space, where ↑ sends it).
60	 */
61	export function WriteCard({ height, insetTop, insetBottom, active, reduceMotion, greeting, onWritingChange, onSubmit, onRecorded, onSpeak, start, onStarted }: WriteCardProps) {
62	  const card = useRef<View>(null);
63	  const [draft, setDraft] = useState('');
64	  const [writing, setWriting] = useState(false);
65	  // How far the keyboard reaches up into the card, so the box can sit just above it.
66	  const keyboardOverlap = useKeyboardOverlap(card);
67	
68	  // How long the last recording ran, read when it stops (the recorder resets after).
69	  const spoken = useRef(0);
70	  const voice = useDreamRecorder((text) => onRecorded(text, spoken.current));
71	  const recording = voice.phase === 'recording';
72	  const busy = voice.phase === 'transcribing';
73	
74	  const hasDraft = wordCount(draft) > 0;
75	  const open = writing || hasDraft;
76	  const boxBottom = Math.max(22, keyboardOverlap + 12);
77	  const boxHeight = Math.max(BOX_CLOSED, Math.min(BOX_OPEN, height - boxBottom - HEADING_ROOM));
78	  const titleTop = open ? TITLE_OPEN_TOP : Math.round((height - HEADING_HEIGHT) / 2);
79	
80	  function startWriting() {
81	    setWriting(true);
82	    onWritingChange(true);
83	  }
84	
85	  useEffect(() => {
86	    if (!start) return;
87	    // Waits for the screen to finish sliding in before opening the keyboard or the mic.
88	    const timer = setTimeout(() => {
89	      if (start === 'type') startWriting();
90	      else onSpeak();
91	      onStarted?.();
92	    }, START_DELAY_MS);
93	    return () => clearTimeout(timer);
94	    // Only a new request should trigger this, not the handlers changing identity.
95	    // eslint-disable-next-line react-hooks/exhaustive-deps
96	  }, [start]);
97	
98	  function stopWriting() {
99	    onWritingChange(false);
100	    // Nothing written: go back to the mic.
101	    if (!hasDraft) setWriting(false);
102	  }
103	
104	  function submit() {
105	    if (!hasDraft) return;
106	    const text = draft.trim();
107	    Keyboard.dismiss();
108	    setDraft('');
109	    setWriting(false);
110	    onSubmit(text);
111	  }
112	
113	  function stopRecording() {
114	    spoken.current = voice.durationMillis / 1000;
115	    voice.stopAndTranscribe();
116	  }
117	
118	  function recordLabel() {
119	    if (recording) return formatClock(voice.durationMillis / 1000);
120	    if (busy) return '…';
121	    return 'record';
122	  }
123	
124	  // The recorder is a small button until it is running, when it takes the big one's size.
125	  const recordSize = recording || busy ? YAP_SIZE : SMALL_SIZE;
126	
127	  return (
128	    <TodayCard
129	      ref={card}
130	      height={height}
131	      insetTop={insetTop}
132	      insetBottom={insetBottom}
133	      active={active}
134	      reduceMotion={reduceMotion}
135	      label="tell your dream"
136	      base="#060a16"
137	      gradient="radial-gradient(80% 35% at 50% 25%, #16543f, transparent 70%)"
138	      photo={CARD_BACKGROUNDS[0]}
139	      glow={{ left: 160, top: 330, width: 260, height: 260, color: '#46ffb4', opacity: 0.12, drift: 'out', duration: 14000 }}>
140	      {/* Tapping the card around the box puts the keyboard away. */}
141	      <Pressable style={StyleSheet.absoluteFill} onPress={Keyboard.dismiss} accessible={false} />
142	      <CardHeading
143	        top={0}
144	        eyebrow={greeting}
145	        title="what did you dream about last night?"
146	        titleStyle={styles.title}
147	        style={[{ top: titleTop }, !reduceMotion && { transitionProperty: 'top', transitionDuration: 500, transitionTimingFunction: EASE_OUT }]}
148	      />
149	
150	      {open ? (
151	        <Animated.View style={[styles.box, { bottom: boxBottom, height: boxHeight }, rise(reduceMotion, 0, 400)]}>
152	          <View style={styles.field}>
153	            <TextInput
154	              value={draft}
155	              onChangeText={setDraft}
156	              onFocus={() => onWritingChange(true)}
157	              onBlur={stopWriting}
158	              autoFocus
159	              multiline
160	              style={styles.input}
161	              placeholder={OPEN_PLACEHOLDER}
162	              placeholderTextColor="rgba(255, 255, 255, 0.7)"
163	              selectionColor={BrandColors.lime}
164	              cursorColor={BrandColors.lime}
165	              textAlignVertical="top"
166	              accessibilityLabel="Write your dream"
167	              accessibilityHint="Then press interpret"
168	            />
169	          </View>
170	          <View style={styles.footer}>
171	            <Text style={styles.hint}>{writeHint(draft, true)}</Text>
172	            <Pressable
173	              accessibilityRole="button"
174	              accessibilityLabel="Interpret"
175	              accessibilityState={{ disabled: !hasDraft }}
176	              disabled={!hasDraft}
177	              onPress={submit}
178	              hitSlop={6}>
179	              <Animated.View
