  useEffect(() => {
    if (!focused) return;
    const to = TABS.indexOf(current);
    if (reduceMotion) position.value = to;
    else {
      position.value = TABS.indexOf(shownTab);
      position.value = withTiming(to, { duration: SLIDE_MS, easing: Easing.out(Easing.cubic) });
    }
    shownTab = current;
  }, [focused, current, reduceMotion, position]);

  const pill = useAnimatedStyle(() => ({
    transform: [{ translateX: BAR_PADDING + position.value * tabWidth + (tabWidth - PILL_WIDTH) / 2 }],
  }));

  function onLayout(event: LayoutChangeEvent) {
    setBarWidth(event.nativeEvent.layout.width);
  }

  /** Where the finger is along the bar, as a tab number (0 is the first tab). */
  function place(x: number) {
    'worklet';
    return clamp((x - LENS_INSET) / tabWidth - 0.5, 0, TABS.length - 1);
  }

  const drag = Gesture.Pan()
    .enabled(floating && tabWidth > 0)
    // Only once the finger has really moved sideways, so tapping a tab still just taps it.
    .activeOffsetX([-8, 8])
    .failOffsetY([-12, 12])
    .onBegin(() => {
      held.value = withTiming(1, { duration: 120 });
    })
    .onUpdate((event) => {
      position.value = place(event.x);
      stretch.value = withTiming(clamp(Math.abs(event.velocityX) / 3000, 0, 0.2), { duration: 90 });
    })
    .onEnd((event) => {
      runOnJS(pick)(TABS[Math.round(place(event.x))]);
