1	/**
2	 * Shares a heading's words out evenly over the lines it takes, so it never trails off with
3	 * one word on its own. React Native has no `text-wrap: balance`, so the breaks are worked
4	 * out here and put in by hand.
5	 */
6	
7	/** How much longer the first line may be than the last when the split is otherwise a tie. */
8	const TILT = 0.03;
9	
10	/** Words never split, so a line can't be shorter than the longest word in it. */
11	function widths(words: string[]) {
12	  const upto = [0];
13	  for (const word of words) upto.push(upto[upto.length - 1] + word.length);
14	  // Characters in words `from`..`to - 1`, with one space between them.
15	  return (from: number, to: number) => upto[to] - upto[from] + (to - from - 1);
16	}
17	
...
20	 */
21	export function balanceText(text: string, lines: number): string {
22	  const words = text.split(/\s+/).filter(Boolean);
23	  const rows = Math.min(lines, words.length);
24	  if (rows < 2) return text;
25	
26	  const width = widths(words);
27	  const share = width(0, words.length) / rows;
28	  // Two splits can be equally even; headings read better when the top line is the longer
29	  // one, so each line's share is tilted a little down the block to break the tie.
30	  const wanted = (row: number) => share * (1 + TILT * (rows - 1 - 2 * (row - 1)));
31	  const cost = (from: number, to: number, row: number) => (width(from, to) - wanted(row)) ** 2;
32	
33	  // best[r][i]: the lowest cost of putting the first i words on r lines, and where that line started.
34	  const best: number[][] = [new Array(words.length + 1).fill(Infinity)];
35	  const start: number[][] = [new Array(words.length + 1).fill(0)];
36	  best[0][0] = 0;
37	  for (let r = 1; r <= rows; r++) {
38	    best.push(new Array(words.length + 1).fill(Infinity));
39	    start.push(new Array(words.length + 1).fill(0));
40	    for (let to = r; to <= words.length; to++) {
41	      for (let from = r - 1; from < to; from++) {
42	        const total = best[r - 1][from] + cost(from, to, r);
43	        if (total < best[r][to]) {
44	          best[r][to] = total;
45	          start[r][to] = from;
46	        }
47	      }
48	    }
49	  }
