24	const BREATHE = {
25	  '0%': { transform: [{ scale: 1 }], opacity: 1 },
26	  '50%': { transform: [{ scale: 1.04 }], opacity: 0.88 },
27	  '100%': { transform: [{ scale: 1 }], opacity: 1 },
28	} as const;
