31	 * The dawn over the top of the paywall. Only its bottom edge shows: the black fade
32	 * the screen lays over it swallows the rest by 42% down.
33	 */
34	export function PaywallAurora({ scale }: { scale: number }) {
35	  const reduceMotion = useReducedMotion();
36	  const width = BOX_WIDTH * scale;
37	  const height = BOX_HEIGHT * scale;
38	
39	  return (
40	    <Animated.View
41	      pointerEvents="none"
42	      style={[
43	        styles.aurora,
44	        { left: BOX_LEFT * scale, top: BOX_TOP * scale, width, height },
45	        loop(reduceMotion, BREATHE, 8000),
46	      ]}>
47	      <Svg width={width} height={height}>
48	        <Defs>
49	          <RadialGradient id="paywall-dawn" cx="50%" cy="50%" rx="50%" ry="50%">
50	            {STOPS.map((stop) => (
51	              <Stop key={stop.offset} offset={stop.offset} stopColor={stop.color} stopOpacity={stop.opacity} />
52	            ))}
53	          </RadialGradient>
54	        </Defs>
55	        <Ellipse cx={width / 2} cy={height / 2} rx={width / 2} ry={height / 2} fill="url(#paywall-dawn)" />
56	      </Svg>
57	    </Animated.View>
58	  );
59	}
60	
